from typing import Sequence, Mapping, Any, List
from unittest.mock import Magic, Mock
from fastapi.dependencies.utils import request_params_to_args

# Mock dependencies
class MockField:
    def __init__(self, name, convert_underscores=True):
        self.name = name
        self.field_info = Mock()
        self.field_info.convert_underscores = convert_underscores

class MockHeaders(Mapping):
    def __init__(self, data):
        self._data = data
    def __getitem__(self, key):
        return self._data.get(key)
    def keys(self):
        return self._data.keys()
    def __iter__(self):
        return iter(self._data)
    def __len__(self):
        return len(self._data)

def get_validation_alias(field):
    return field.name

def _get_multidict_value(field, received_params, alias=None):
    # Simple mock: return the value if it exists in received_params
    if alias in received_params:
        return received_params[alias]
    return None

# Test case: convert_underscores=True (default)
# Header name contains underscore: "my_header"
fields = [MockField(name="my_header", convert_underscores=True)]
received_params = MockHeaders({"my_header": "test_value"})

# Expected behavior: The header should be rejected because convert_underscores=True
# and the header name contains '_'.
values, errors = request_params_to_args(fields, received_params)

print(f"Test 1 (Underscore Header, convert_underscores=True):")
print(f"Values: {values}")
assert values == {}

# Test case: convert_underscores=False
# Header name contains underscore: "my_header"
fields_false = [MockField(name="my_header", convert_underscores=False)]
received_params_false = MockHeaders({"my_header": "test_value"})

# Expected behavior: Should process it, converting to hyphen if necessary (though here it's just processing)
# Since convert_underscores=False, the conversion logic (alias.replace("_", "-")) is skipped.
# The alias remains "my_header".
