print(f"Test 2 (Underscore Header, convert_underscores=False):")
print(f"Values: {values_false}")
assert values_false == {"my_header": "test_value"}

# Test case: Hyphenated header, convert_underscores=True
# Header name contains hyphen: "my-header"
fields_hyphen = [MockField(name="my-header", convert_underscores=True)]
received_params_hyphen = MockHeaders({"my-header": "test_value"})

# Expected behavior: Should process it, converting to hyphen if necessary (it already is)
